# MARCATORE_RACCOGLI_SCALPER_CLAUDIO_v1
# Raccolta (SOLO COPIA + ZIP) dei risultati parziali di RIGA_LANCIA_SCALPER_CLAUDIO e delle ultime righe dei giornali del tester degli ultimi 8 ore.
# Scrive SOLO: una cartella in %TEMP%, uno zip in Desktop\ABTG_RISULTATI e apre Esplora risorse. NON chiude ne apre MT5, NON tocca terminali, EA, conti, VPS.
$ErrorActionPreference='Continue'; if($env:COMPUTERNAME -ne 'DESKTOP-H4D7CAJ'){ Write-Host ('SOLO sul PC di backtest DESKTOP-H4D7CAJ. Qui: ' + $env:COMPUTERNAME) -ForegroundColor Red; return }; $ris=Join-Path ([Environment]::GetFolderPath('Desktop')) 'ABTG_RISULTATI'; $cart=@(Get-ChildItem -LiteralPath $ris -Directory -Filter 'ANNO_ORO_GRADINI_SCALPERCLAUDIO_*' -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1); if($cart.Count -eq 0){ Write-Host 'Cartella ANNO_ORO_GRADINI_SCALPERCLAUDIO_* NON trovata in Desktop\ABTG_RISULTATI.' -ForegroundColor Red; return }; $src=$cart[0].FullName; Write-Host ('Cartella trovata: ' + $src) -ForegroundColor Cyan; $tmp=Join-Path $env:TEMP ('zip_scalper_' + (Get-Date).ToString('yyyyMMdd_HHmmss')); New-Item -ItemType Directory -Force -Path $tmp | Out-Null; Copy-Item -LiteralPath $src -Destination (Join-Path $tmp $cart[0].Name) -Recurse -Force -ErrorAction SilentlyContinue; $lg=Join-Path $tmp 'giornali_tester'; New-Item -ItemType Directory -Force -Path $lg | Out-Null; $n=0; foreach($f in @(Get-ChildItem -LiteralPath (Join-Path $env:APPDATA 'MetaQuotes') -Recurse -File -Filter '*.log' -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -gt (Get-Date).AddHours(-8) -and ($_.FullName -like '*\Tester\*\logs\*' -or $_.FullName -like '*\Terminal\*\logs\*') } | Sort-Object LastWriteTime -Descending | Select-Object -First 12)){ $n++; $dest=Join-Path $lg (('{0:00}_' -f $n) + $f.Directory.Parent.Name + '_' + $f.Name + '.txt'); try { Get-Content -LiteralPath $f.FullName -Tail 4000 -ErrorAction Stop | Set-Content -LiteralPath $dest -Encoding UTF8 } catch { } }; Write-Host ('giornali copiati (ultime 4000 righe ciascuno): ' + $n) -ForegroundColor Cyan; $zip=Join-Path $ris ($cart[0].Name + '_PARZIALE_' + (Get-Date).ToString('HHmm') + '.zip'); try { Compress-Archive -Path (Join-Path $tmp '*') -DestinationPath $zip -Force; $mb=[math]::Round((Get-Item -LiteralPath $zip).Length/1MB,1); Write-Host ('ZIP DA MANDARE: ' + $zip + '   (' + $mb + ' MB)') -ForegroundColor Green; if($mb -gt 10){ Write-Host 'ATTENZIONE: oltre 10 MB. Mandami prima solo la cartella giornali_tester.' -ForegroundColor Yellow }; Start-Process -FilePath 'explorer.exe' -ArgumentList ('/select,' + [char]34 + $zip + [char]34) } catch { Write-Host ('zip NON creato: ' + $_.Exception.Message) -ForegroundColor Red }
